/* Launch Radar — a dark instrument panel. One palette, one spacing scale, monospace numerals so
   columns line up down the board. No external fonts, no images, no network. */

:root {
  --bg: #06090f;
  --bg-soft: #0a0f18;
  --panel: #0d1421;
  --panel-hi: #121b2b;
  --line: #1b2637;
  --line-hi: #26364d;
  --ink: #e8eef8;
  --ink-dim: #9aabc2;
  --ink-faint: #6b7d95;
  --mint: #34e2c4;
  --mint-dim: #166b60;
  --lime: #c2f05c;
  --amber: #f5b544;
  --rose: #ff7a7a;
  --radius: 10px;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Inter, sans-serif;
  --step-1: 7px;
  --step-2: 12px;
  --step-3: 18px;
  --step-4: 26px;
  --step-5: 38px;
}

* { box-sizing: border-box; }

html { background: var(--bg); color-scheme: dark; }

body {
  margin: 0;
  padding: var(--step-4) clamp(14px, 3vw, 40px) 80px;
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(1100px 520px at 8% -12%, rgba(52, 226, 196, 0.09), transparent 60%),
    radial-gradient(900px 460px at 96% -8%, rgba(194, 240, 92, 0.05), transparent 62%),
    var(--bg);
  min-height: 100vh;
}

.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip {
  position: absolute; left: -999px; top: 8px; z-index: 50;
  background: var(--mint); color: #04211c; padding: 8px 14px; border-radius: 6px; font-weight: 700;
}
.skip:focus { left: 12px; }

/* ---- masthead ---------------------------------------------------------- */

.masthead {
  display: flex; flex-wrap: wrap; gap: var(--step-4);
  align-items: flex-start; justify-content: space-between;
  max-width: 1560px; margin: 0 auto var(--step-4);
  padding-bottom: var(--step-3); border-bottom: 1px solid var(--line);
}

.brand { display: flex; gap: var(--step-3); align-items: center; }

.mark { display: grid; gap: 3px; width: 30px; }
.mark i {
  display: block; height: 3px; border-radius: 2px; background: var(--mint);
  animation: sweep 3.4s ease-in-out infinite;
}
.mark i:nth-child(1) { width: 30px; opacity: 0.35; }
.mark i:nth-child(2) { width: 21px; opacity: 0.65; animation-delay: 0.25s; background: var(--lime); }
.mark i:nth-child(3) { width: 12px; animation-delay: 0.5s; }
@keyframes sweep { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(0.45); } }

h1 { margin: 0; font-size: 21px; letter-spacing: -0.015em; font-weight: 700; }
.tagline { margin: 2px 0 0; color: var(--ink-dim); font-size: 13px; }

.provenance { display: flex; gap: var(--step-4); margin: 0; flex-wrap: wrap; }
.provenance div { display: flex; flex-direction: column; gap: 1px; }
.provenance dt { font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-faint); }
.provenance dd { margin: 0; font-family: var(--mono); font-size: 13px; color: var(--ink); }

/* ---- model strip ------------------------------------------------------- */

.model-strip {
  max-width: 1560px; margin: 0 auto var(--step-3);
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px;
  padding: var(--step-2) var(--step-3);
  background: linear-gradient(90deg, rgba(52, 226, 196, 0.07), rgba(194, 240, 92, 0.03) 55%, transparent);
  border: 1px solid var(--line); border-left: 3px solid var(--mint);
  border-radius: var(--radius); color: var(--ink-dim); font-size: 12.5px;
}
.model-strip b { color: var(--ink); font-weight: 600; }
.model-strip code {
  font-family: var(--mono); font-size: 12px; color: var(--lime);
  background: rgba(0, 0, 0, 0.35); padding: 2px 7px; border-radius: 5px; white-space: nowrap;
}

/* ---- stats ------------------------------------------------------------- */

.stats {
  max-width: 1560px; margin: 0 auto var(--step-3);
  display: grid; grid-template-columns: repeat(auto-fit, minmax(148px, 1fr)); gap: 10px;
}
.stat {
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: var(--step-2) var(--step-3);
}
.stat .k { font-size: 10px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ink-faint); }
.stat .v { font-family: var(--mono); font-size: 19px; margin-top: 3px; color: var(--ink); letter-spacing: -0.01em; }
.stat .s { font-size: 11.5px; color: var(--ink-faint); margin-top: 1px; }
.stat.accent .v { color: var(--mint); }

/* ---- controls ---------------------------------------------------------- */

.controls {
  max-width: 1560px; margin: 0 auto var(--step-2);
  display: flex; flex-wrap: wrap; gap: 10px; align-items: flex-end;
}

.search { flex: 1 1 260px; }
.search input {
  width: 100%; padding: 9px 12px; font: inherit; color: var(--ink);
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
}
.search input::placeholder { color: var(--ink-faint); }

.pick { display: flex; flex-direction: column; gap: 3px; }
.pick span { font-size: 10px; letter-spacing: 0.09em; text-transform: uppercase; color: var(--ink-faint); }
.pick select {
  padding: 9px 10px; font: inherit; font-size: 13px; color: var(--ink);
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px; min-width: 140px;
}

.search input:focus-visible, .pick select:focus-visible, .tabs button:focus-visible,
th button:focus-visible, .detail-close:focus-visible, .rowbtn:focus-visible {
  outline: 2px solid var(--mint); outline-offset: 1px;
}

.tabs { display: flex; gap: 2px; padding: 3px; background: var(--panel); border: 1px solid var(--line); border-radius: 9px; margin-left: auto; }
.tabs button {
  font: inherit; font-size: 12.5px; color: var(--ink-dim); background: none; border: 0;
  padding: 7px 13px; border-radius: 6px; cursor: pointer;
}
.tabs button[aria-selected="true"] { background: var(--panel-hi); color: var(--ink); box-shadow: inset 0 0 0 1px var(--line-hi); }

/* ---- board ------------------------------------------------------------- */

main { max-width: 1560px; margin: 0 auto; }

.result-line { color: var(--ink-dim); font-size: 12.5px; margin: 0 0 8px; }
.result-line b { color: var(--ink); }

.table-wrap {
  border: 1px solid var(--line); border-radius: var(--radius); overflow: auto;
  background: var(--panel); max-height: 62vh;
}

table { width: 100%; border-collapse: collapse; font-size: 13px; }

thead th {
  position: sticky; top: 0; z-index: 2;
  background: #0b1220; text-align: left; font-weight: 600;
  border-bottom: 1px solid var(--line-hi); padding: 0; white-space: nowrap;
}
thead th button {
  font: inherit; font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--ink-faint); background: none; border: 0; padding: 10px 12px; cursor: pointer; width: 100%; text-align: inherit;
}
thead th button:hover { color: var(--ink); }
thead th[aria-sort="descending"] button, thead th[aria-sort="ascending"] button { color: var(--mint); }
th.num button, td.num { text-align: right; }
th.num, td.num { font-family: var(--mono); }

tbody tr { border-bottom: 1px solid rgba(27, 38, 55, 0.7); cursor: pointer; }
tbody tr:hover { background: rgba(52, 226, 196, 0.05); }
tbody tr.is-sel { background: rgba(52, 226, 196, 0.1); box-shadow: inset 2px 0 0 var(--mint); }
tbody tr:last-child { border-bottom: 0; }

td { padding: 8px 12px; vertical-align: middle; }
td.rank { color: var(--ink-faint); font-family: var(--mono); width: 46px; }
td.rank b { color: var(--ink); font-weight: 600; }

.name-cell { display: flex; flex-direction: column; gap: 1px; min-width: 190px; }
.name-cell .nm { font-weight: 600; color: var(--ink); }
.name-cell .sub { font-size: 11.5px; color: var(--ink-faint); }

.chip {
  display: inline-block; padding: 2px 7px; border-radius: 999px; font-size: 10.5px;
  border: 1px solid var(--line-hi); color: var(--ink-dim); background: rgba(0, 0, 0, 0.25); white-space: nowrap;
}
.chip.watch { border-color: var(--mint-dim); color: var(--mint); }
.chip.live { border-color: #4a3a12; color: var(--amber); }

.value-cell { display: flex; align-items: center; justify-content: flex-end; gap: 9px; }
.value-cell .num { min-width: 82px; }
.bar { width: 62px; height: 5px; border-radius: 3px; background: #142034; overflow: hidden; flex: none; }
.bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--mint-dim), var(--mint)); }

.up { color: var(--mint); }
.down { color: var(--rose); }
.mute { color: var(--ink-faint); }

.rowbtn { all: unset; cursor: pointer; display: block; width: 100%; }

.empty { color: var(--ink-dim); padding: var(--step-4) 0; text-align: center; }
.footnote { color: var(--ink-faint); font-size: 11.5px; margin-top: 10px; line-height: 1.6; }

/* ---- detail drawer ----------------------------------------------------- */

.detail {
  position: fixed; top: 0; right: 0; height: 100vh; width: min(460px, 96vw);
  background: var(--bg-soft); border-left: 1px solid var(--line-hi);
  box-shadow: -24px 0 60px rgba(0, 0, 0, 0.55);
  transform: translateX(102%); transition: transform 0.22s ease;
  overflow-y: auto; padding: var(--step-4) var(--step-3) 48px; z-index: 20;
}
.detail[aria-hidden="false"] { transform: none; }

.detail-close {
  position: absolute; top: 14px; right: 14px; width: 30px; height: 30px;
  display: grid; place-items: center; font-size: 18px; line-height: 1;
  color: var(--ink-dim); background: var(--panel); border: 1px solid var(--line); border-radius: 7px; cursor: pointer;
}

.detail h2 { margin: 0 0 2px; font-size: 19px; letter-spacing: -0.01em; padding-right: 40px; }
.detail .lede { margin: 0 0 var(--step-3); color: var(--ink-dim); font-size: 12.5px; }

.detail .figures { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; margin-bottom: var(--step-3); }
.detail .figures div { background: var(--panel); padding: 9px 11px; }
.detail .figures .k { font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-faint); }
.detail .figures .v { font-family: var(--mono); font-size: 14.5px; }

.detail h3 {
  font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-faint);
  margin: var(--step-3) 0 8px; font-weight: 600;
}

.derivation { font-family: var(--mono); font-size: 12px; color: var(--ink-dim); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 11px 13px; }
.derivation .eq { color: var(--ink); }
.derivation .eq em { color: var(--lime); font-style: normal; }
.derivation .eq strong { color: var(--mint); }
.derivation .note { display: block; margin-top: 6px; color: var(--ink-faint); font-family: var(--sans); font-size: 11.5px; line-height: 1.5; }

.steps { list-style: none; margin: 0; padding: 0; counter-reset: step; }
.steps li {
  position: relative; padding: 0 0 14px 30px; counter-increment: step;
  border-left: 1px solid var(--line); margin-left: 9px;
}
.steps li:last-child { border-left-color: transparent; padding-bottom: 0; }
.steps li::before {
  content: counter(step); position: absolute; left: -9px; top: 0;
  width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center;
  font-family: var(--mono); font-size: 10px; color: var(--bg);
  background: var(--mint); font-weight: 700;
}
.steps .txt { font-size: 12.8px; color: var(--ink); }
.steps .meta { font-family: var(--mono); font-size: 11px; color: var(--ink-faint); margin-top: 3px; }

.tagrow { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }

@media (max-width: 720px) {
  .provenance { display: none; }
  .tabs { margin-left: 0; width: 100%; }
  td.rank, th.rank { display: none; }
  .bar { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mark i { animation: none; }
  .detail { transition: none; }
}
```

