      panel.appendChild(p);
    } else {
      var ol = el('ol', 'steps');
      (rec.farm_steps || []).forEach(function (step) {
        var li = el('li');
        // A step is "action. Cost: … . Time: … ." — split the cost and time back out for the meta line.
        var m = /^(.*?)\s*Cost:\s*(.*?)\.\s*Time:\s*(.*?)\.\s*$/.exec(step);
